/**
 * Replay store — PostgreSQL persistence for the match event log.
 *
 * Schema (created idempotently on init):
 * - `matches`       — one row per played match: id (uuid, generated by the
 *                     game server), lobby code, start/end dates, result and
 *                     snapshots of settings + roster.
 * - `match_events`  — the append-only event log: every recorded action as a
 *                     jsonb row, ordered by (match_id, seq). seq is assigned
 *                     by the recorder in arrival order, so a replay can be
 *                     re-driven deterministically from the rows alone.
 * - `match_players` — per-player stats of a match, derived from the event
 *                     stream when it is sealed (and backfilled for matches
 *                     recorded before this table existed). The leaderboard
 *                     and player pages aggregate over these rows.
 *
 * All methods throw on failure — error handling lives in the service layer,
 * which must never let a DB problem break the game.
 */
import pg from 'pg'

export function createPgStore(databaseUrl) {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 5 })
  // An idle-client error (e.g. the DB going away) must not crash the process.
  pool.on('error', (err) => console.error('[replay] pg pool error:', err.message))

  let initialized = null

  /**
   * Create the schema if needed. Retries in the background until the DB is
   * reachable (docker-compose `depends_on: service_healthy` usually beats us
   * to it; this covers plain `node src/index.js` boots against a slow DB).
   */
  function init() {
    if (!initialized) {
      initialized = (async () => {
        for (;;) {
          try {
            await pool.query(`
              CREATE TABLE IF NOT EXISTS matches (
                id          UUID PRIMARY KEY,
                lobby_code  TEXT NOT NULL,
                started_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
                ended_at    TIMESTAMPTZ,
                winner      TEXT,
                reason      TEXT,
                settings    JSONB NOT NULL DEFAULT '{}'::jsonb,
                players     JSONB NOT NULL DEFAULT '[]'::jsonb,
                event_count INTEGER NOT NULL DEFAULT 0
              );
              CREATE TABLE IF NOT EXISTS match_events (
                match_id UUID    NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
                seq      INTEGER NOT NULL,
                at       TIMESTAMPTZ NOT NULL,
                event    TEXT    NOT NULL,
                payload  JSONB   NOT NULL,
                PRIMARY KEY (match_id, seq)
              );
              CREATE TABLE IF NOT EXISTS match_players (
                match_id  UUID    NOT NULL REFERENCES matches(id) ON DELETE CASCADE,
                player_id TEXT    NOT NULL,
                name      TEXT    NOT NULL,
                role      TEXT    NOT NULL DEFAULT 'hider',
                captured  BOOLEAN NOT NULL DEFAULT false,
                survived  BOOLEAN NOT NULL DEFAULT false,
                won       BOOLEAN NOT NULL DEFAULT false,
                captures  INTEGER NOT NULL DEFAULT 0,
                exposures INTEGER NOT NULL DEFAULT 0,
                distance_m REAL   NOT NULL DEFAULT 0,
                fix_count INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (match_id, player_id)
              );
              CREATE INDEX IF NOT EXISTS match_players_name_idx
                ON match_players (lower(btrim(name)));
              -- Columns added after the table first shipped (idempotent).
              ALTER TABLE match_players ADD COLUMN IF NOT EXISTS survived_pct REAL NOT NULL DEFAULT 0;
              ALTER TABLE match_players ADD COLUMN IF NOT EXISTS catch_pct_sum REAL NOT NULL DEFAULT 0;
            `)
            return
          } catch (err) {
            console.error('[replay] schema init failed, retrying in 5 s:', err.message)
            await new Promise((r) => setTimeout(r, 5000))
          }
        }
      })()
    }
    return initialized
  }

  async function insertMatch(match) {
    // { id, lobbyCode, startedAt, settings, players }
    await pool.query(
      `INSERT INTO matches (id, lobby_code, started_at, settings, players)
       VALUES ($1, $2, $3, $4, $5)`,
      [match.id, match.lobbyCode, match.startedAt, JSON.stringify(match.settings ?? {}), JSON.stringify(match.players ?? [])],
    )
  }

  /** Append a batch of events: [{ seq, at, event, payload }] in seq order. */
  async function insertEvents(matchId, rows) {
    if (!rows.length) return
    // Multi-row insert in chunks that stay far below the 65535-param limit
    // (4 params per row → 500 rows = 2000 params).
    for (let i = 0; i < rows.length; i += 500) {
      const chunk = rows.slice(i, i + 500)
      const values = []
      const params = []
      chunk.forEach((row, j) => {
        const b = j * 4
        values.push(`($1, $${b + 2}, $${b + 3}, $${b + 4}, $${b + 5})`)
        params.push(row.seq, row.at, row.event, JSON.stringify(row.payload ?? {}))
      })
      await pool.query(
        `INSERT INTO match_events (match_id, seq, at, event, payload)
         VALUES ${values.join(',')}`,
        [matchId, ...params],
      )
    }
  }

  async function finishMatch(matchId, { endedAt, winner, reason, eventCount }) {
    await pool.query(
      `UPDATE matches
       SET ended_at = $2, winner = $3, reason = $4, event_count = $5
       WHERE id = $1`,
      [matchId, endedAt, winner, reason, eventCount],
    )
  }

  /** Persist one match's derived player stats (replaces any existing rows). */
  async function insertPlayerStats(matchId, rows) {
    await pool.query(`DELETE FROM match_players WHERE match_id = $1`, [matchId])
    if (!rows?.length) return
    // 12 params per row (+ the fixed $1 match_id) → 50 rows per statement
    // stays far below the 65535-param limit.
    for (let i = 0; i < rows.length; i += 50) {
      const chunk = rows.slice(i, i + 50)
      const values = []
      const params = []
      chunk.forEach((r, j) => {
        const b = j * 12 // row j's own params start at $2 (match_id stays $1)
        values.push(
          `($1, $${b + 2}, $${b + 3}, $${b + 4}, $${b + 5}, $${b + 6}, $${b + 7}, $${b + 8}, $${b + 9}, $${b + 10}, $${b + 11}, $${b + 12}, $${b + 13})`,
        )
        params.push(
          r.playerId,
          r.name ?? '?',
          r.role ?? 'hider',
          !!r.captured,
          !!r.survived,
          !!r.won,
          r.captures ?? 0,
          r.exposures ?? 0,
          r.distanceM ?? 0,
          r.fixCount ?? 0,
          r.survivedPct ?? 0,
          r.catchPctSum ?? 0,
        )
      })
      await pool.query(
        `INSERT INTO match_players
           (match_id, player_id, name, role, captured, survived, won, captures, exposures, distance_m, fix_count, survived_pct, catch_pct_sum)
         VALUES ${values.join(',')}`,
        [matchId, ...params],
      )
    }
  }

  /** Ended matches that have no stats rows yet (boot-time backfill). */
  async function matchesWithoutStats() {
    const { rows } = await pool.query(
      `SELECT m.id FROM matches m
       WHERE m.ended_at IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM match_players mp WHERE mp.match_id = m.id)`,
    )
    return rows.map((r) => r.id)
  }

  /**
   * Leaderboard across all matches — one row per player (name, grouped
   * case-insensitively; the display name is the most recent spelling).
   */
  async function leaderboard({ limit = 100 } = {}) {
    const { rows } = await pool.query(
      `SELECT lower(btrim(mp.name)) AS key,
              (array_agg(btrim(mp.name) ORDER BY m.started_at DESC NULLS LAST))[1] AS name,
              count(*)::int AS matches,
              coalesce(sum(CASE WHEN mp.won THEN 1 ELSE 0 END), 0)::int AS wins,
              coalesce(sum(CASE WHEN mp.role = 'hider' THEN 1 ELSE 0 END), 0)::int AS "hiderMatches",
              coalesce(sum(CASE WHEN mp.role = 'hunter' THEN 1 ELSE 0 END), 0)::int AS "hunterMatches",
              coalesce(sum(CASE WHEN mp.role = 'hider' AND mp.captured THEN 1 ELSE 0 END), 0)::int AS "timesCaught",
              coalesce(sum(CASE WHEN mp.role = 'hider' AND mp.survived THEN 1 ELSE 0 END), 0)::int AS "timesSurvived",
              coalesce(sum(mp.captures), 0)::int AS captures,
              coalesce(sum(mp.exposures), 0)::int AS exposures,
              coalesce(sum(mp.distance_m), 0) AS "distanceM",
              -- Ø % of match time survived as a hider (null without hider games).
              avg(CASE WHEN mp.role = 'hider' THEN mp.survived_pct END) AS "avgSurvivedPct",
              -- Ø % of match time per catch as a hunter.
              CASE WHEN coalesce(sum(mp.captures), 0) > 0
                   THEN coalesce(sum(mp.catch_pct_sum), 0) / sum(mp.captures)
                   END AS "avgCatchPct"
       FROM match_players mp
       JOIN matches m ON m.id = mp.match_id
       GROUP BY lower(btrim(mp.name))
       ORDER BY wins DESC, matches DESC, "distanceM" DESC
       LIMIT $1`,
      [limit],
    )
    return rows
  }

  /** Aggregated stats of ONE player plus their recent matches, or null. */
  async function playerStats(name) {
    const key = String(name ?? '').trim()
    if (!key) return null
    const agg = await pool.query(
      `SELECT coalesce(sum(CASE WHEN mp.won THEN 1 ELSE 0 END), 0)::int AS wins,
              coalesce(sum(CASE WHEN mp.role = 'hider' THEN 1 ELSE 0 END), 0)::int AS "hiderMatches",
              coalesce(sum(CASE WHEN mp.role = 'hunter' THEN 1 ELSE 0 END), 0)::int AS "hunterMatches",
              coalesce(sum(CASE WHEN mp.role = 'hider' AND mp.captured THEN 1 ELSE 0 END), 0)::int AS "timesCaught",
              coalesce(sum(CASE WHEN mp.role = 'hider' AND mp.survived THEN 1 ELSE 0 END), 0)::int AS "timesSurvived",
              coalesce(sum(mp.captures), 0)::int AS captures,
              coalesce(sum(mp.exposures), 0)::int AS exposures,
              coalesce(sum(mp.distance_m), 0) AS "distanceM",
              avg(CASE WHEN mp.role = 'hider' THEN mp.survived_pct END) AS "avgSurvivedPct",
              CASE WHEN coalesce(sum(mp.captures), 0) > 0
                   THEN coalesce(sum(mp.catch_pct_sum), 0) / sum(mp.captures)
                   END AS "avgCatchPct",
              count(*)::int AS matches
       FROM match_players mp
       WHERE lower(btrim(mp.name)) = lower($1)`,
      [key],
    )
    const stats = agg.rows[0]
    if (!stats || stats.matches === 0) return null
    const { rows } = await pool.query(
      `SELECT m.id, m.lobby_code AS "lobbyCode", m.started_at AS "startedAt", m.winner,
              mp.role, mp.captured, mp.survived, mp.won, mp.captures, mp.exposures, mp.distance_m AS "distanceM"
       FROM match_players mp
       JOIN matches m ON m.id = mp.match_id
       WHERE lower(btrim(mp.name)) = lower($1)
       ORDER BY m.started_at DESC
       LIMIT 50`,
      [key],
    )
    return { name: rows[0]?.name ?? key, stats, matches: rows }
  }

  async function listMatches({ limit = 100 } = {}) {
    const { rows } = await pool.query(
      `SELECT id, lobby_code AS "lobbyCode", started_at AS "startedAt", ended_at AS "endedAt",
              winner, reason, event_count AS "eventCount",
              jsonb_array_length(players) AS "playerCount"
       FROM matches
       ORDER BY started_at DESC
       LIMIT $1`,
      [limit],
    )
    return rows
  }

  async function getMatch(id) {
    const { rows } = await pool.query(
      `SELECT id, lobby_code AS "lobbyCode", started_at AS "startedAt", ended_at AS "endedAt",
              winner, reason, settings, players, event_count AS "eventCount"
       FROM matches
       WHERE id = $1`,
      [id],
    )
    return rows[0] ?? null
  }

  async function getEvents(id) {
    const { rows } = await pool.query(
      `SELECT seq, at, event, payload
       FROM match_events
       WHERE match_id = $1
       ORDER BY seq`,
      [id],
    )
    return rows
  }

  return {
    init,
    insertMatch,
    insertEvents,
    finishMatch,
    insertPlayerStats,
    matchesWithoutStats,
    leaderboard,
    playerStats,
    listMatches,
    getMatch,
    getEvents,
  }
}
